def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for c in text:
        if c.islower():
            base = ord('a')
        elif c.isupper():
            base = ord('A')
        else:
            result.append(c)
            continue
        shifted = (ord(c) - base + shift) % 26
        result.append(chr(base + shifted))
    return ''.join(result)
```

