import string

def word_frequency(text: str) -> dict[str, int]:
    words = text.split()
    punct = string.punctuation
    freq = {}
    for word in words:
        stripped = word.strip(punct).lower()
        if stripped:
            freq[stripped] = freq.get(stripped, 0) + 1
    return freq
